// Prompt: "Agents read projects over MCP"
// Changes: Targets of the read tools – what an agent points a tool at – and their resolution to content. Each target
//          kind is one resolver; a resolved target carries a JSON reference (echoed in tool results), its project and
//          its content: the target's four parts over the project's current export naming and simulation inputs.

import { readParts, writeParts } from '#/lib/parts'
import type { ProjectData } from '#/lib/project'
import { z } from 'zod'
import type { DraftRecord, ProjectRecord, ProjectStore, SnapshotSummary } from '../projects.server'
import { ToolError } from './tools.server'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Agents create, edit and discard drafts"
// Changes: Drafts are targets too: a draft's parts over its project's export naming and simulation inputs, with its
//          own snapshots; a snapshot of a draft names its draft. Write tools resolve the draft they may change here.
/** Target kinds. */
export const TARGET_KINDS = ['project', 'draft', 'snapshot'] as const
export type TargetKind = (typeof TARGET_KINDS)[number]

/** A resolved target. */
export interface Target {
  /** How the target is shown in tool results: kind, id, owning project and version details. */
  ref: { kind: TargetKind; id: string | number; projectId: string } & Record<string, unknown>
  project: ProjectRecord
  /** The target's parts with its project's export naming and simulation inputs (those are never versioned per target). */
  data: ProjectData
  /** The target's own history, for targets that have one (projects, drafts); snapshots have none. */
  listSnapshots?: () => SnapshotSummary[]
}

type Resolver = (id: string | number, store: ProjectStore) => Target

function projectOf(store: ProjectStore, id: string) {
  const project = store.getProject(id)
  if (!project) throw new ToolError(`No project with id "${id}". Use list_projects to find project ids.`)
  return project
}

function draftOf(store: ProjectStore, id: string) {
  const draft = store.getDraft(id)
  if (!draft) throw new ToolError(`No draft with id "${id}". Use list_drafts on a project to find draft ids.`)
  return draft
}

const draftRef = (draft: DraftRecord) => ({
  kind: 'draft' as const,
  id: draft.id,
  projectId: draft.projectId,
  label: draft.label,
  state: draft.state,
  revision: draft.revision,
})

// One resolver per target kind.
const RESOLVERS: Record<TargetKind, Resolver> = {
  project(id, store) {
    const project = projectOf(store, String(id))
    return {
      ref: { kind: 'project', id: project.id, projectId: project.id, revision: project.revision },
      project,
      data: project.data,
      listSnapshots: () => store.listSnapshots(project.id),
    }
  },

  draft(id, store) {
    const draft = draftOf(store, String(id))
    const project = projectOf(store, draft.projectId)
    return {
      ref: draftRef(draft),
      project,
      data: writeParts(project.data, draft.parts),
      listSnapshots: () => store.listDraftSnapshots(draft.id),
    }
  },

  snapshot(id, store) {
    const snapshotId = typeof id === 'number' ? id : /^\d+$/.test(id) ? Number(id) : NaN
    const snapshot = Number.isSafeInteger(snapshotId) ? store.getSnapshot(snapshotId) : null
    if (!snapshot) throw new ToolError(`No snapshot with id ${JSON.stringify(id)}. Use list_snapshots on a project to find snapshot ids.`)
    const project = projectOf(store, snapshot.projectId)
    return {
      ref: {
        kind: 'snapshot',
        id: snapshot.id,
        projectId: project.id,
        ...(snapshot.draftId !== null && { draftId: snapshot.draftId }),
        label: snapshot.label,
        snapshotKind: snapshot.kind,
        createdAt: snapshot.createdAt,
      },
      project,
      data: writeParts(project.data, readParts(snapshot.data)),
    }
  },
}

export const targetSchema = z
  .object({
    kind: z
      .enum(TARGET_KINDS)
      .describe('project: the project as it is now; draft: an editable copy of a project\'s parts; snapshot: a frozen earlier version of a project or draft'),
    id: z
      .union([z.string(), z.number()])
      .describe('Project id (text, from list_projects), draft id (text, from list_drafts) or snapshot id (number, from list_snapshots)'),
  })
  .describe('What to read: {"kind":"project","id":"<project id>"}, {"kind":"draft","id":"<draft id>"} or {"kind":"snapshot","id":<snapshot id>}')

export type TargetInput = z.infer<typeof targetSchema>

export const resolveTarget = (store: ProjectStore, target: TargetInput): Target => RESOLVERS[target.kind](target.id, store)

/** The open draft a write tool may change; projects, snapshots and ended drafts are refused with the reason. */
export function writableDraft(store: ProjectStore, target: TargetInput): DraftRecord {
  if (target.kind === 'project') {
    throw new ToolError(
      `Projects are never written by agents. Create a draft of project "${target.id}" with create_draft and write to ` +
        '{"kind":"draft","id":"<draft id>"}; the human reviews and adopts it.',
    )
  }
  if (target.kind === 'snapshot') {
    throw new ToolError('A snapshot is a frozen earlier version and cannot be changed. Write to an open draft instead.')
  }
  const draft = draftOf(store, String(target.id))
  if (draft.state !== 'open') throw endedDraftError(draft)
  return draft
}

export const endedDraftError = (draft: DraftRecord) =>
  new ToolError(
    `Draft "${draft.id}" ("${draft.label}") was ${draft.state} at ${draft.endedAt}; ended drafts are read-only. ` +
      'Create a new draft with create_draft to propose further changes.',
  )

export { draftOf, draftRef, projectOf }
